import re
import sys

values = {}

assignment = re.compile(
    r"(\w+)\s*<-\s*(?:(\d+)|\(\s*(\w+)\s*([+-])\s*(\d+)\s*\)\s*mod\s*(\d+))"
)

for statement in sys.stdin.read().split(";"):
    statement = statement.strip()
    if not statement:
        continue

    match = assignment.fullmatch(statement)
    if not match:
        raise ValueError(f"Invalid assignment: {statement}")

    target, literal, source, operator, amount, modulus = match.groups()
    if literal is not None:
        values[target] = int(literal)
    else:
        result = values[source] + (1 if operator == "+" else -1) * int(amount)
        values[target] = result % int(modulus)

print("; ".join(f"{name} ?= {values[name]}" for name in
                ("a", "b", "c", "d", "e", "f", "g", "h", "TMP")) + ";")
